import{_ as i,C as t,o,c,j as e,a,E as d,a2 as l}from"./chunks/framework.CdvW4CUT.js";const f=JSON.parse('{"title":"Bytecode Transformer & Underlying Network Protocol (module.sync:processor / management / network)","description":"","frontmatter":{},"headers":[],"relativePath":"en/26.3/sync/processor-and-network.md","filePath":"en/26.3/sync/processor-and-network.md"}'),r={name:"en/26.3/sync/processor-and-network.md"};function h(y,s,p,k,g,E){const n=t("BranchContextCard");return o(),c("div",null,[s[0]||(s[0]=e("h1",{id:"bytecode-transformer-underlying-network-protocol-module-sync-processor-management-network",tabindex:"-1"},[a("Bytecode Transformer & Underlying Network Protocol ("),e("code",null,"module.sync:processor"),a(" / "),e("code",null,"management"),a(" / "),e("code",null,"network"),a(") "),e("a",{class:"header-anchor",href:"#bytecode-transformer-underlying-network-protocol-module-sync-processor-management-network","aria-label":'Permalink to "Bytecode Transformer & Underlying Network Protocol (`module.sync:processor` / `management` / `network`)"'},"​")],-1)),d(n,{branch:"26.3"}),s[1]||(s[1]=l('<p>Why don&#39;t developers need to write <code>proxy.setParent(this)</code> in constructors or manually register/unregister objects with a manager when using <code>@Sync</code> and <code>@LazySync</code>? This page explains <code>module.sync:processor</code>&#39;s ASM bytecode injection, <code>LazySyncManager</code>&#39;s weak-reference snapshot anti-loop mechanism, and configuration-phase ID map syncing.</p><hr><h2 id="_1-compile-time-indexing-load-time-asm-bytecode-injection-module-sync-processor" tabindex="-1">1. Compile-Time Indexing &amp; Load-Time ASM Bytecode Injection (<code>module.sync:processor</code>) <a class="header-anchor" href="#_1-compile-time-indexing-load-time-asm-bytecode-injection-module-sync-processor" aria-label="Permalink to &quot;1. Compile-Time Indexing &amp; Load-Time ASM Bytecode Injection (`module.sync:processor`)&quot;">​</a></h2><p><code>SyncClassProcessor</code> implements NeoForge&#39;s <code>net.neoforged.neoforgespi.transformation.ClassProcessor</code> (<code>anvillib_sync:processor</code>), transparently rewriting classes containing <code>@Sync</code> or <code>@LazySync</code> during startup class loading:</p><h3 id="_1-syncbytecodeinjector-for-sync-classes" tabindex="-1">1. <code>SyncBytecodeInjector</code> (For <code>@Sync</code> Classes) <a class="header-anchor" href="#_1-syncbytecodeinjector-for-sync-classes" aria-label="Permalink to &quot;1. `SyncBytecodeInjector` (For `@Sync` Classes)&quot;">​</a></h3><p>When a class is annotated with <code>@Sync</code>, scans all <code>ACC_FINAL</code> fields of type <code>SyncProxy</code>:</p><ul><li><strong>For instance <code>final SyncProxy</code> fields</strong>: injects before every <code>RETURN</code> in every constructor <code>&lt;init&gt;</code>:<div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.field </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setParent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFieldName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;field&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDirection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SyncDirection.XXX); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Only if the field did not specify its own direction</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>For <code>static final SyncProxy</code> fields</strong>: injects before every <code>RETURN</code> in <code>&lt;clinit&gt;</code> (creating <code>&lt;clinit&gt;</code> if absent):<div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (Owner.field </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Owner.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setParent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Owner.class);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Owner.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFieldName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;field&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Owner.field.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDirection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(SyncDirection.XXX);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li></ul><h3 id="_2-lazysyncbytecodeinjector-for-classes-with-lazysync-fields" tabindex="-1">2. <code>LazySyncBytecodeInjector</code> (For Classes with <code>@LazySync</code> Fields) <a class="header-anchor" href="#_2-lazysyncbytecodeinjector-for-classes-with-lazysync-fields" aria-label="Permalink to &quot;2. `LazySyncBytecodeInjector` (For Classes with `@LazySync` Fields)&quot;">​</a></h3><p>When a class has any <code>@LazySync</code>-annotated field:</p><ul><li><strong>If instance <code>@LazySync</code> fields exist</strong>: injects before every <code>RETURN</code> in each <code>&lt;init&gt;</code>:<div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AnvilLibSync.LAZY_SYNC_MANAGER.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">track</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div></li><li><strong>If static <code>@LazySync</code> fields exist</strong>: injects before every <code>RETURN</code> in <code>&lt;clinit&gt;</code>:<div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AnvilLibSync.LAZY_SYNC_MANAGER.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trackStatic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Owner.class);</span></span></code></pre></div></li></ul><hr><h2 id="_2-lazysyncmanager-weak-reference-tracking-anti-loop-design" tabindex="-1">2. <code>LazySyncManager</code> Weak-Reference Tracking &amp; Anti-Loop Design <a class="header-anchor" href="#_2-lazysyncmanager-weak-reference-tracking-anti-loop-design" aria-label="Permalink to &quot;2. `LazySyncManager` Weak-Reference Tracking &amp; Anti-Loop Design&quot;">​</a></h2><ol><li><strong>Automatic GC Reclamation (No Manual <code>untrack</code> Needed)</strong>: <code>LazySyncManager</code> stores <code>instances</code> and <code>snapshots</code> using Guava&#39;s <strong><code>new MapMaker().weakKeys()</code> (weak keys + identity <code>==</code> equality)</strong>. Once a <code>BlockEntity</code> or <code>Entity</code> unloads from the world and loses external strong references, the JVM GC reclaims it automatically with zero memory leaks.</li><li><strong>Initial Baseline &amp; Loop Suppression</strong>: <ul><li>The first time <code>scanTarget</code> scans a newly constructed object, it stores the initial encoded bytes in <code>snapshots</code> as a baseline without sending an initial packet;</li><li>When the receiver gets <code>LazySyncPayload</code> and writes fields back via <code>applyGrouped</code>, it <strong>immediately re-encodes the newly written values into its own <code>snapshots</code></strong>, ensuring the next tick&#39;s scan does not mistake the synced values for local changes and echo them back (eliminating bidirectional sync loops).</li><li>Note: for <code>C2S</code> or <code>BOTH</code> on <code>SyncProxy</code> / <code>@LazySync</code>, when the <strong>server</strong> receives an update from a client, it updates local state and broadcasts the change to other clients tracking that object.</li></ul></li></ol><hr><h2 id="_3-configuration-phase-field-id-dictionary-sync-syncconfigmanager" tabindex="-1">3. Configuration-Phase Field ID Dictionary Sync (<code>SyncConfigManager</code>) <a class="header-anchor" href="#_3-configuration-phase-field-id-dictionary-sync-syncconfigmanager" aria-label="Permalink to &quot;3. Configuration-Phase Field ID Dictionary Sync (`SyncConfigManager`)&quot;">​</a></h2><p>To avoid sending verbose <code>&quot;com.example.HeaterBlockEntity#temperature&quot;</code> strings in every sync packet:</p><ol><li>During <code>FMLCommonSetupEvent</code>, <code>SyncConfigManager.compileContent()</code> scans all mods&#39; <code>@Sync</code> classes (<code>final SyncProxy</code> fields) and <code>@LazySync</code> fields, assigning a compact integer <code>configId</code> to each <code>&quot;ClassName#fieldName&quot;</code>;</li><li>When a player connects (<code>RegisterConfigurationTasksEvent</code>), <code>AnvilLibSync.SyncConfig</code> (<code>anvillib_sync:sync_config</code>) sends <code>SyncConfigurationPayload</code> (<code>Map&lt;Integer, String&gt;</code>) to the client, which adopts it and replies with <code>SyncConfigurationFinishPayload</code>.</li></ol><hr><h2 id="_4-internal-management-network-classes-apistatus-internal" tabindex="-1">4. Internal Management &amp; Network Classes (<code>@ApiStatus.Internal</code>) <a class="header-anchor" href="#_4-internal-management-network-classes-apistatus-internal" aria-label="Permalink to &quot;4. Internal Management &amp; Network Classes (`@ApiStatus.Internal`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Package / Class</th><th style="text-align:left;">Core Responsibility</th></tr></thead><tbody><tr><td style="text-align:left;"><code>AnvilLibSync</code></td><td style="text-align:left;">Module main class holding <code>SYNC_MANAGER</code>, <code>SYNC_CONFIG_MANAGER</code>, and <code>LAZY_SYNC_MANAGER</code> singletons.</td></tr><tr><td style="text-align:left;"><code>SyncManager</code></td><td style="text-align:left;">Manages <code>SyncRegisterEntry</code> host mappings and handles immediate packet sending on <code>SyncProxy#setValue</code>.</td></tr><tr><td style="text-align:left;"><code>LazySyncManager</code></td><td style="text-align:left;">Manages weak-reference sets of <code>@LazySync</code> instances/static classes, byte snapshot diffing, and grouped batch send/apply.</td></tr><tr><td style="text-align:left;"><code>SyncConfigManager</code></td><td style="text-align:left;">Scans and maintains the <code>&quot;ClassName#fieldName&quot; &lt;-&gt; int</code> index map.</td></tr><tr><td style="text-align:left;"><code>SideUtil</code></td><td style="text-align:left;">Provides cross-side <code>RegistryAccess</code> lookup, built-in <code>entityFinder</code> / <code>blockEntityFinder</code>, and smart <code>serverSend</code> routing (<code>sendToPlayersTrackingChunk</code> / <code>sendToPlayersTrackingEntity</code> / <code>sendToPlayersInDimension</code>).</td></tr><tr><td style="text-align:left;"><code>SyncPayload</code> / <code>LazySyncPayload</code></td><td style="text-align:left;">Immediate single-field sync packet (<code>anvillib_sync:sync</code>) and lazy multi-field grouped sync packet (<code>anvillib_sync:lazy_sync</code>).</td></tr><tr><td style="text-align:left;"><code>SyncConfigurationPayload</code> / <code>SyncConfigurationFinishPayload</code></td><td style="text-align:left;">Configuration-phase field ID dictionary sync packet and ack packet.</td></tr></tbody></table>',20))])}const u=i(r,[["render",h]]);export{f as __pageData,u as default};
